import type { ReactElement, ReactNode } from "react";

export type FeatureGateProps = {
  flag: FeatureFlagKey;
  fallback?: ReactNode;
  children?: ReactNode;
};

/** The flag twin of `PermissionGate`: `readFlag` consults the snapshot the
